arguments.new_str:
using System.Diagnostics;
using System.Runtime.CompilerServices;
using TextAnalysis;

// Setup
var small = new TextAnalyzer("The quick brown fox jumps over the lazy dog near the river bank");
var rng = new Random(42);
var words = new string[1000];
for (int i = 0; i < words.Length; i++)
{
    int len = rng.Next(2, 12);
    var chars = new char[len];
    for (int j = 0; j < len; j++)
        chars[j] = (char)('a' + rng.Next(0, 26));
    words[i] = new string(chars);
}
var large = new TextAnalyzer(string.Join(' ', words));

string runtime = System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription;
Console.WriteLine($"Runtime: {runtime}");
Console.WriteLine($"{"Method",-35} {"Mean",>12} {"Allocated",>12}");
Console.WriteLine(new string('-', 61));

Bench("AverageWordLength_Small", () => small.AverageWordLength());
Bench("AverageWordLength_Large", () => large.AverageWordLength());
Bench("WordLengthHistogram_Small", () => small.WordLengthHistogram());
Bench("WordLengthHistogram_Large", () => large.WordLengthHistogram());
Bench("UniqueWordCount_Small", () => small.UniqueWordCount());
Bench("UniqueWordCount_Large", () => large.UniqueWordCount());

static void Bench(string name, Action action, int warmup = 100, int iterations = 100_000)
{
    // Warmup
    for (int i = 0; i < warmup; i++) action();
    GC.Collect();
    GC.WaitForPendingFinalizers();
    GC.Collect();

    long memBefore = GC.GetTotalAllocatedBytes(precise: true);
    var sw = Stopwatch.StartNew();
    for (int i = 0; i < iterations; i++) action();
    sw.Stop();
    long memAfter = GC.GetTotalAllocatedBytes(precise: true);

    double nsPerOp = (double)sw.Elapsed.TotalNanoseconds / iterations;
    double bytesPerOp = (double)(memAfter - memBefore) / iterations;

    string meanStr = nsPerOp < 1000 ? $"{nsPerOp:F2} ns" : $"{nsPerOp / 1000:F2} us";
    string allocStr = bytesPerOp < 1 ? "0 B" : $"{bytesPerOp:F0} B";
    Console.WriteLine($"{name,-35} {meanStr,>12} {allocStr,>12}");
}

